# Part of the Sellora test suite. Needs: pip install playwright pillow  and  python -m playwright install chromium
import os as _os, pathlib as _pl
HERE=_os.path.dirname(_os.path.abspath(__file__)); _os.chdir(HERE); _os.makedirs('shots',exist_ok=True)
APP=_os.path.abspath(_os.path.join(HERE,'..','Sellora_Seller_Center.html')); APP_URL=_pl.Path(APP).as_uri()
from playwright.sync_api import sync_playwright
URL=APP_URL; R=[]
def check(n,c,i=''): R.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n+(' | '+str(i) if i else ''))
W=lambda pg,ms=150: pg.wait_for_timeout(ms)
with sync_playwright() as p:
    b=p.chromium.launch()
    # ---- sandboxed preview: forms blocked by the frame ----
    pg=b.new_page(viewport={'width':1120,'height':900}); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto(_pl.Path(_os.path.join(HERE,'preview_frame.html')).as_uri()); W(pg,800); fr=pg.frame_locator('#f')
    check('preview: warns that this window cannot save', 'cannot save data' in fr.locator('#lf').inner_text())
    fr.locator('#l-name').fill('S'); fr.locator('#l-email').fill('a@mail.com'); fr.locator('#l-pass').fill('secret12'); fr.locator('#lf button[type=submit]').click(); W(pg,600)
    check('preview: Create account works even though the frame blocks forms', fr.locator('main h1').count()>0)
    fr.locator('.navb[data-p=products]').click(); W(pg); fr.locator('main [data-act=addProd]').first.click(); W(pg)
    fr.locator('#f-name').fill('Pen'); fr.locator('#f-price').fill('20'); fr.locator('#f-stock').fill('5'); fr.locator('#f-name').press('Enter'); W(pg,300)
    check('preview: Enter in the product form saves it', 'Pen' in fr.locator('#plist').inner_text())
    fr.locator('.navb[data-p=customers]').click(); W(pg); fr.locator('main [data-act=addCust]').first.click(); W(pg); fr.locator('#cu-name').fill('Mint'); fr.locator('#cuf button[type=submit]').click(); W(pg)
    fr.locator('.navb[data-p=orders]').click(); W(pg); fr.locator('main [data-act=addOrder]').first.click(); W(pg); fr.locator('#o-cust').select_option(label='Mint'); fr.locator('#items select').select_option(index=1); W(pg)
    fr.locator('#of button[type=submit]').dblclick(); W(pg,500)
    check('preview: order created once, even with a double click', 'ORD-10001' in fr.locator('main h1').inner_text() and pg.frames[1].evaluate("1"), fr.locator('main h1').inner_text())
    fr.locator('[data-act=prof]').click(); fr.locator('[data-act=logout]').click(); W(pg,300)
    fr.locator('#l-email').fill('a@mail.com'); fr.locator('#l-pass').fill('secret12'); fr.locator('#l-pass').press('Enter'); W(pg,500)
    check('preview: log in again with Enter', fr.locator('main h1').count()>0)
    fr.locator('[data-act=prof]').click(); fr.locator('[data-act=logout]').click(); W(pg,300); fr.locator('[data-act=demo]').click(); W(pg,600)
    check('preview: Try with sample data works too', fr.locator('main h1').count()>0 and fr.locator('.memwarn.demo').count()==1)
    check('preview: no page errors', not errs, errs[:2]); pg.close()
    # ---- normal window ----
    pg=b.new_page(viewport={'width':1280,'height':800}); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto(URL); W(pg,400)
    hero=pg.evaluate("document.querySelector('.lbrand>div:nth-child(2)').getBoundingClientRect().toJSON()"); mini=pg.evaluate("document.querySelector('.lmini').getBoundingClientRect().toJSON()")
    check('desktop: feature cards sit right under the headline card and fully on screen', 10<=mini['top']-hero['bottom']<=40 and mini['bottom']<=800, f"gap {round(mini['top']-hero['bottom'])}px, cards bottom {round(mini['bottom'])}px")
    check('desktop: cards line up with the headline card', abs(mini['width']-hero['width'])<2 and abs(mini['left']-hero['left'])<2)
    pg.click('[data-act=freshShop]'); W(pg,300)
    check('Start from scratch: sign-up form, cursor in "Your name"', pg.evaluate("document.activeElement.id")=='l-name' and 'Create your store' in pg.inner_text('#lf'))
    pg.fill('#l-name','Sunisa'); pg.fill('#l-email','s@mail.com'); pg.fill('#l-pass','secret12'); pg.click('#lf button[type=submit]'); W(pg,400)
    check('Start from scratch: empty shop with the Get started steps', 'Get started' in pg.inner_text('main') and pg.evaluate("JSON.parse(localStorage.getItem('sellora-d-s@mail.com')).orders.length")==0)
    pg.click('[data-act=prof]'); pg.click('[data-act=logout]'); W(pg,300)
    pg.fill('#l-email','nobody@mail.com'); pg.fill('#l-pass','whatever1'); pg.click('#lf button[type=submit]'); W(pg,300)
    check('login with an email not in this browser explains why', 'no account with this email in this browser' in pg.inner_text('#l-email-e'), pg.inner_text('#l-email-e'))
    pg.fill('#l-email','s@mail.com'); pg.fill('#l-pass','wrongpass'); pg.click('#lf button[type=submit]'); W(pg,300)
    check('wrong password says so', 'password is not right' in pg.inner_text('#l-pass-e'))
    pg.click('[data-act=demo]'); W(pg,500)
    d=pg.evaluate("JSON.parse(localStorage.getItem('sellora-d-demo@sellora.app'))")
    check('Try with sample data: demo shop with a year of orders, demo banner', d['settings']['store']=='Lotus Demo Shop' and len(d['orders'])==d['lastOrderId']-10000>1000 and 'demo1234' in pg.inner_text('.memwarn.demo'))
    pg.click('.navb[data-p=products]'); pg.click('main [data-act=addProd] >> nth=0'); W(pg); pg.fill('#f-name','Demo Item'); pg.fill('#f-price','9'); pg.click('#pf button[type=submit]'); W(pg)
    pg.click('[data-act=prof]'); pg.click('[data-act=logout]'); W(pg,300); pg.click('[data-act=demo]'); W(pg,500); pg.click('.navb[data-p=products]'); W(pg)
    check('demo again: opens the same demo shop with your changes', 'Demo Item' in pg.inner_text('#plist'))
    pg.click('[data-act=prof]'); pg.click('[data-act=logout]'); W(pg,300)
    pg.fill('#l-email','demo@sellora.app'); pg.fill('#l-pass','demo1234'); pg.click('#lf button[type=submit]'); W(pg,400)
    check('demo login also works by hand (demo@sellora.app / demo1234)', pg.query_selector('.memwarn.demo') is not None)
    pg.click('[data-act=ownShop]'); W(pg,300)
    check('"Start my own shop" logs out of the demo and opens sign-up', pg.query_selector('#l-name') is not None and pg.evaluate("document.activeElement.id")=='l-name')
    check('normal window: no page errors', not errs, errs[:2]); pg.close()
    for w,h in [(666,559),(390,844),(1280,800),(1440,900)]:
        pg=b.new_page(viewport={'width':w,'height':h}); pg.goto(URL); W(pg,400); pg.screenshot(path=f'shots/v9-login-{w}.png',full_page=(w<900))
        print(w,'page scrolls sideways:',pg.evaluate('document.documentElement.scrollWidth')>w); pg.close()
    b.close()
print(f'\n{sum(R)}/{len(R)} passed')
